#include <coroutine>
#include <functional>
#include <exception>
#include <cassert>
#include <type_traits>
#include <utility>
struct Promise;
struct Task {
    using promise_type = Promise;
    std::coroutine_handle<Promise> handle;
};
struct Promise {
    int value = 0;
    Task get_return_object() {
        return {std::coroutine_handle<Promise>::from_promise(*this)};
    }
    std::suspend_always initial_suspend() noexcept { return {}; }
    std::suspend_always final_suspend() noexcept { return {}; }
    void return_value(int result) noexcept { value = result; }
    void unhandled_exception() { std::terminate(); }
};
Task produce() { co_return 7; }
int main() {
    auto task = produce();
    auto handle = task.handle;
    assert(handle && !handle.done());
    auto address = handle.address();
    auto recovered = std::coroutine_handle<Promise>::from_address(address);
    assert(recovered == handle);
    auto fromPromise = std::coroutine_handle<Promise>::from_promise(handle.promise());
    assert(fromPromise == handle);
    std::coroutine_handle<> erased = handle;
    std::coroutine_handle<> assigned;
    assigned = erased;
    assert(assigned.address() == address);
    assert(std::hash<std::coroutine_handle<>>{}(erased) ==
        std::hash<std::coroutine_handle<>>{}(assigned));
    handle.resume();
    assert(handle.promise().value == 7 && handle.done());
    handle.destroy();
    task.handle = nullptr;
    std::suspend_always always;
    std::suspend_never never;
    assert(!always.await_ready() && never.await_ready());
    auto noop = std::noop_coroutine();
    std::noop_coroutine_promise &promise = noop.promise();
    (void)promise;
    noop.resume();
    assert(!noop.done());
}
